DROP TABLE IF EXISTS `evaluation_response_event`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `evaluation_response_event` (
  `evaluation_response_event_id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `evaluation_response_id` bigint(20) unsigned DEFAULT NULL,
  `student_evaluation_task_id` bigint(20) unsigned NOT NULL,
  `created_by_user_id` bigint(20) unsigned NOT NULL,
  `event_type` enum('Draft Saved','Answer Cleared','Proceeded To Review','Submitted','Reset Progress','Logout Warning Shown') NOT NULL,
  `event_description` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`evaluation_response_event_id`),
  KEY `fk_response_event_response` (`evaluation_response_id`),
  KEY `fk_response_event_task` (`student_evaluation_task_id`),
  KEY `fk_response_event_user` (`created_by_user_id`),
  CONSTRAINT `fk_response_event_response` FOREIGN KEY (`evaluation_response_id`) REFERENCES `evaluation_response` (`evaluation_response_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_response_event_task` FOREIGN KEY (`student_evaluation_task_id`) REFERENCES `student_evaluation_task` (`student_evaluation_task_id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_response_event_user` FOREIGN KEY (`created_by_user_id`) REFERENCES `user` (`user_id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=292 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

