CREATE TABLE `evaluation_result_release` (
  `evaluation_result_release_id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `evaluation_period_id` bigint(20) unsigned DEFAULT NULL,
  `release_name` varchar(150) NOT NULL,
  `release_status` enum('Draft','Released','Unreleased','Revoked') NOT NULL DEFAULT 'Released',
  `release_scope_type` enum('All','Department','Course','Year Level','Section','Subject','Faculty') NOT NULL DEFAULT 'All',
  `release_department_id` bigint(20) unsigned DEFAULT NULL,
  `release_course_id` bigint(20) unsigned DEFAULT NULL,
  `release_year_level` tinyint(3) unsigned DEFAULT NULL,
  `release_section_id` bigint(20) unsigned DEFAULT NULL,
  `release_subject_id` bigint(20) unsigned DEFAULT NULL,
