  `release_scope_label` varchar(255) DEFAULT NULL,
  `released_by_admin_id` bigint(20) unsigned DEFAULT NULL,
  `released_at` datetime DEFAULT NULL,
  `release_note` varchar(255) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`evaluation_result_release_id`),
  KEY `fk_result_release_admin` (`released_by_admin_id`),
  KEY `idx_release_period` (`evaluation_period_id`),
  KEY `idx_release_status` (`release_status`),
  KEY `idx_release_scope` (`release_scope_type`),
  KEY `idx_release_academic_term` (`release_academic_year_id`,`release_term_id`),
  KEY `idx_release_scope_ids` (`release_department_id`,`release_course_id`,`release_year_level`,`release_section_id`,`release_subject_id`,`release_faculty_id`),
  CONSTRAINT `fk_result_release_admin` FOREIGN KEY (`released_by_admin_id`) REFERENCES `admin` (`admin_id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_result_release_period` FOREIGN KEY (`evaluation_period_id`) REFERENCES `evaluation_period` (`evaluation_period_id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
