DROP TABLE IF EXISTS `student_section_enrollment`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `student_section_enrollment` (
  `student_section_enrollment_id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `student_id` bigint(20) unsigned NOT NULL,
  `section_id` bigint(20) unsigned NOT NULL,
  `term_id` bigint(20) unsigned NOT NULL,
  `enrollment_status` enum('Active','Dropped','Transferred','Completed') NOT NULL DEFAULT 'Active',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`student_section_enrollment_id`),
  UNIQUE KEY `uq_student_section_term` (`student_id`,`section_id`,`term_id`),
  KEY `fk_student_section_enrollment_section` (`section_id`),
  KEY `fk_student_section_enrollment_term` (`term_id`),
  CONSTRAINT `fk_student_section_enrollment_section` FOREIGN KEY (`section_id`) REFERENCES `section` (`section_id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_student_section_enrollment_student` FOREIGN KEY (`student_id`) REFERENCES `student` (`student_id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_student_section_enrollment_term` FOREIGN KEY (`term_id`) REFERENCES `term` (`term_id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=176 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

