CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_compute_faculty_result`(
    IN p_evaluation_period_id BIGINT UNSIGNED,
    IN p_teaching_assignment_id BIGINT UNSIGNED,
    IN p_result_release_id BIGINT UNSIGNED
)
BEGIN
    DECLARE v_form_id BIGINT UNSIGNED;
    DECLARE v_result_id BIGINT UNSIGNED;
    DECLARE v_eligible_count INT DEFAULT 0;
    DECLARE v_submitted_count INT DEFAULT 0;
    DECLARE v_pending_count INT DEFAULT 0;
    DECLARE v_participation_rate DECIMAL(6,2) DEFAULT 0;
    DECLARE v_overall_average DECIMAL(5,2);
    DECLARE v_total_answer_count INT DEFAULT 0;

    SELECT evaluation_form_id
    INTO v_form_id
    FROM evaluation_form
    WHERE evaluation_period_id = p_evaluation_period_id
      AND form_status = 'Active'
    ORDER BY form_version DESC
    LIMIT 1;

    SELECT COUNT(*)
    INTO v_eligible_count
    FROM student_evaluation_task
    WHERE evaluation_period_id = p_evaluation_period_id
      AND teaching_assignment_id = p_teaching_assignment_id
      AND is_active = 1;

    SELECT COUNT(*)
    INTO v_submitted_count
    FROM student_evaluation_task
    WHERE evaluation_period_id = p_evaluation_period_id
      AND teaching_assignment_id = p_teaching_assignment_id
      AND task_status = 'Submitted'
      AND is_active = 1;

    SET v_pending_count = v_eligible_count - v_submitted_count;

    IF v_eligible_count > 0 THEN
        SET v_participation_rate = ROUND((v_submitted_count / v_eligible_count) * 100, 2);
    END IF;

    SELECT ROUND(AVG(er.average_score), 2)
    INTO v_overall_average
    FROM evaluation_response er
    JOIN student_evaluation_task setask
        ON setask.student_evaluation_task_id = er.student_evaluation_task_id
    WHERE er.evaluation_period_id = p_evaluation_period_id
      AND er.teaching_assignment_id = p_teaching_assignment_id
      AND er.response_status = 'Submitted'
      AND setask.task_status = 'Submitted'
      AND setask.is_active = 1;

    INSERT INTO faculty_evaluation_result (
        evaluation_result_release_id,
        teaching_assignment_id,
        evaluation_period_id,
        evaluation_form_id,
        eligible_student_count,
        submitted_response_count,
        pending_response_count,
        participation_rate,
        overall_average_score,
        result_status,
        computed_at,
        released_at
    )
    VALUES (
        p_result_release_id,
        p_teaching_assignment_id,
        p_evaluation_period_id,
        v_form_id,
        v_eligible_count,
        v_submitted_count,
        v_pending_count,
        v_participation_rate,
        v_overall_average,
        'Released',
        CURRENT_TIMESTAMP,
        CURRENT_TIMESTAMP
    )
    ON DUPLICATE KEY UPDATE
        faculty_evaluation_result_id = LAST_INSERT_ID(faculty_evaluation_result_id),
        eligible_student_count = VALUES(eligible_student_count),
        submitted_response_count = VALUES(submitted_response_count),
        pending_response_count = VALUES(pending_response_count),
        participation_rate = VALUES(participation_rate),
        overall_average_score = VALUES(overall_average_score),
        result_status = 'Released',
        computed_at = CURRENT_TIMESTAMP,
        released_at = CURRENT_TIMESTAMP;

    SET v_result_id = LAST_INSERT_ID();

    DELETE FROM faculty_result_category_score
    WHERE faculty_evaluation_result_id = v_result_id;

    INSERT INTO faculty_result_category_score (
        faculty_evaluation_result_id,
        evaluation_form_category_id,
        average_score,
        percentage_score,
        rating_description
    )
    SELECT
        v_result_id,
        efc.evaluation_form_category_id,
        ROUND(AVG(era.rating_value), 2),
        ROUND((AVG(era.rating_value) / 5) * 100, 2),
        CASE
            WHEN AVG(era.rating_value) >= 4.50 THEN 'Excellent'
            WHEN AVG(era.rating_value) >= 3.50 THEN 'Very Good'
            WHEN AVG(era.rating_value) >= 2.50 THEN 'Good'
            WHEN AVG(era.rating_value) >= 1.50 THEN 'Fair'
            ELSE 'Needs Improvement'
        END
    FROM evaluation_response er
    JOIN student_evaluation_task setask
        ON setask.student_evaluation_task_id = er.student_evaluation_task_id
    JOIN evaluation_response_answer era
        ON era.evaluation_response_id = er.evaluation_response_id
    JOIN evaluation_form_item efi
        ON efi.evaluation_form_item_id = era.evaluation_form_item_id
    JOIN evaluation_form_category efc
        ON efc.evaluation_form_category_id = efi.evaluation_form_category_id
    WHERE er.evaluation_period_id = p_evaluation_period_id
      AND er.teaching_assignment_id = p_teaching_assignment_id
      AND er.response_status = 'Submitted'
      AND setask.task_status = 'Submitted'
      AND setask.is_active = 1
    GROUP BY efc.evaluation_form_category_id;

    DELETE FROM faculty_result_item_score
    WHERE faculty_evaluation_result_id = v_result_id;

    INSERT INTO faculty_result_item_score (
        faculty_evaluation_result_id,
        evaluation_form_item_id,
        average_score,
        response_count
    )
    SELECT
        v_result_id,
        era.evaluation_form_item_id,
        ROUND(AVG(era.rating_value), 2),
        COUNT(*)
    FROM evaluation_response er
    JOIN student_evaluation_task setask
        ON setask.student_evaluation_task_id = er.student_evaluation_task_id
    JOIN evaluation_response_answer era
        ON era.evaluation_response_id = er.evaluation_response_id
    WHERE er.evaluation_period_id = p_evaluation_period_id
      AND er.teaching_assignment_id = p_teaching_assignment_id
      AND er.response_status = 'Submitted'
      AND setask.task_status = 'Submitted'
      AND setask.is_active = 1
    GROUP BY era.evaluation_form_item_id;

    DELETE FROM faculty_result_rating_distribution
    WHERE faculty_evaluation_result_id = v_result_id;

    SELECT COUNT(*)
    INTO v_total_answer_count
    FROM evaluation_response er
    JOIN student_evaluation_task setask
        ON setask.student_evaluation_task_id = er.student_evaluation_task_id
    JOIN evaluation_response_answer era
        ON era.evaluation_response_id = er.evaluation_response_id
    WHERE er.evaluation_period_id = p_evaluation_period_id
      AND er.teaching_assignment_id = p_teaching_assignment_id
      AND er.response_status = 'Submitted'
      AND setask.task_status = 'Submitted'
      AND setask.is_active = 1;

    INSERT INTO faculty_result_rating_distribution (
        faculty_evaluation_result_id,
        rating_scale_option_id,
        rating_count,
        rating_percentage
    )
    SELECT
        v_result_id,
        rso.rating_scale_option_id,
        COALESCE(dist.rating_count, 0),
        CASE
            WHEN v_total_answer_count > 0
            THEN ROUND((COALESCE(dist.rating_count, 0) / v_total_answer_count) * 100, 2)
            ELSE 0
        END
    FROM rating_scale_option rso
    LEFT JOIN (
        SELECT
            era.rating_scale_option_id,
            COUNT(*) AS rating_count
        FROM evaluation_response er
        JOIN student_evaluation_task setask
            ON setask.student_evaluation_task_id = er.student_evaluation_task_id
        JOIN evaluation_response_answer era
            ON era.evaluation_response_id = er.evaluation_response_id
        WHERE er.evaluation_period_id = p_evaluation_period_id
          AND er.teaching_assignment_id = p_teaching_assignment_id
          AND er.response_status = 'Submitted'
          AND setask.task_status = 'Submitted'
          AND setask.is_active = 1
        GROUP BY era.rating_scale_option_id
    ) dist
        ON dist.rating_scale_option_id = rso.rating_scale_option_id
    WHERE rso.evaluation_form_id = v_form_id;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
