CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_register_faculty`(
    IN p_role_id BIGINT UNSIGNED,
    IN p_university_id VARCHAR(50),
    IN p_email VARCHAR(150),
    IN p_password_hash VARCHAR(255),
    IN p_faculty_number VARCHAR(50),
    IN p_first_name VARCHAR(100),
    IN p_middle_name VARCHAR(100),
    IN p_last_name VARCHAR(100),
    IN p_department_id BIGINT UNSIGNED,
    IN p_position VARCHAR(100),
    IN p_academic_rank VARCHAR(100),
    IN p_employment_status VARCHAR(100),
    IN p_contact_number VARCHAR(30)
)
BEGIN
    DECLARE v_user_id BIGINT UNSIGNED;
    DECLARE v_full_name VARCHAR(255);

    SET v_full_name = TRIM(CONCAT(p_first_name, ' ', IFNULL(p_middle_name, ''), ' ', p_last_name));

    START TRANSACTION;

    INSERT INTO `user` (
        role_id,
        university_id,
        email,
        password_hash,
        account_status,
        is_two_factor_enabled
    )
    VALUES (
        p_role_id,
        p_university_id,
        p_email,
        p_password_hash,
        'Active',
        1
    );

    SET v_user_id = LAST_INSERT_ID();

    INSERT INTO faculty (
        user_id,
        faculty_number,
        email,
        contact_number,
        first_name,
        middle_name,
        last_name,
        full_name,
        department_id,
        position,
        academic_rank,
        employment_status,
        faculty_status
    )
    VALUES (
        v_user_id,
        p_faculty_number,
        p_email,
        p_contact_number,
        p_first_name,
        p_middle_name,
        p_last_name,
        v_full_name,
        p_department_id,
        p_position,
        p_academic_rank,
        p_employment_status,
        'Active'
    );

    COMMIT;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ZERO_IN_DATE,NO_ZERO_DATE,NO_ENGINE_SUBSTITUTION' */ ;
