CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_register_student`(
    IN p_role_id BIGINT UNSIGNED,
    IN p_university_id VARCHAR(50),
    IN p_email VARCHAR(150),
    IN p_password_hash VARCHAR(255),
    IN p_student_number VARCHAR(50),
    IN p_first_name VARCHAR(100),
    IN p_middle_name VARCHAR(100),
    IN p_last_name VARCHAR(100),
    IN p_course_id BIGINT UNSIGNED,
    IN p_year_level TINYINT UNSIGNED,
    IN p_section_id BIGINT UNSIGNED,
    IN p_contact_number VARCHAR(30)
)
BEGIN
    DECLARE v_user_id BIGINT UNSIGNED;
    DECLARE v_full_name VARCHAR(255);

    SET v_full_name = TRIM(CONCAT(p_first_name, ' ', IFNULL(p_middle_name, ''), ' ', p_last_name));

    START TRANSACTION;

    INSERT INTO `user` (
        role_id,
        university_id,
        email,
        password_hash,
        account_status,
        is_two_factor_enabled
    )
    VALUES (
        p_role_id,
        p_university_id,
        p_email,
        p_password_hash,
        'Active',
        1
    );

    SET v_user_id = LAST_INSERT_ID();

    INSERT INTO student (
        user_id,
        student_number,
        email,
        first_name,
        middle_name,
        last_name,
        full_name,
        course_id,
        current_year_level,
        current_section_id,
        contact_number,
        student_status,
        guidelines_accepted
    )
    VALUES (
        v_user_id,
        p_student_number,
        p_email,
        p_first_name,
        p_middle_name,
        p_last_name,
        v_full_name,
        p_course_id,
        p_year_level,
        p_section_id,
        p_contact_number,
        'Active',
        0
    );

    COMMIT;
END ;;
DELIMITER ;
