/*!50003 DROP PROCEDURE IF EXISTS `sp_release_evaluation_results` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_release_evaluation_results`(IN `p_evaluation_period_id` BIGINT UNSIGNED, IN `p_admin_id` BIGINT UNSIGNED, IN `p_release_name` VARCHAR(150))
BEGIN
    DECLARE v_done INT DEFAULT 0;
    DECLARE v_assignment_id BIGINT UNSIGNED;
    DECLARE v_release_id BIGINT UNSIGNED;

    DECLARE cur_assignment CURSOR FOR
        SELECT DISTINCT teaching_assignment_id
        FROM student_evaluation_task
        WHERE evaluation_period_id = p_evaluation_period_id;

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = 1;

    START TRANSACTION;

    INSERT INTO evaluation_result_release (
        evaluation_period_id,
        release_name,
        release_status,
        released_by_admin_id,
        released_at
    )
    VALUES (
        p_evaluation_period_id,
        p_release_name,
        'Released',
        p_admin_id,
        CURRENT_TIMESTAMP
    );

    SET v_release_id = LAST_INSERT_ID();

    OPEN cur_assignment;

    assignment_loop:LOOP
        FETCH cur_assignment INTO v_assignment_id;

        IF v_done = 1 THEN
            LEAVE assignment_loop;
        END IF;

        CALL sp_compute_faculty_result(
            p_evaluation_period_id,
            v_assignment_id,
            v_release_id
        );
    END LOOP;

    CLOSE cur_assignment;

    COMMIT;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
