CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_admin_summary`(IN `p_generated_by_user_id` BIGINT UNSIGNED, IN `p_filter_term_id` BIGINT UNSIGNED)
BEGIN
    CALL sp_generate_report_record(
        p_generated_by_user_id,
        'Overall Summary',
        'Preview',
        NULL,
        p_filter_term_id,
        NULL,
        NULL,
        NULL,
        NULL,
        NULL,
        NULL,
        NULL
    );

    SELECT
        COUNT(DISTINCT student_id) AS total_students,
        SUM(total_required_evaluations) AS total_required_evaluations,
        SUM(completed_evaluations) AS completed_evaluations,
        SUM(pending_evaluations) AS pending_evaluations,
        CASE
            WHEN SUM(total_required_evaluations) > 0
            THEN ROUND(SUM(completed_evaluations) / SUM(total_required_evaluations) * 100, 2)
            ELSE 0
        END AS completion_rate
    FROM v_admin_submission_monitoring;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
