/*!50003 DROP PROCEDURE IF EXISTS `sp_reset_student_evaluation_progress` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_reset_student_evaluation_progress`(
    IN p_student_id BIGINT UNSIGNED,
    IN p_evaluation_period_id BIGINT UNSIGNED,
    IN p_reset_reason VARCHAR(255)
)
BEGIN
    DECLARE v_period_id BIGINT UNSIGNED;
    DECLARE v_term_id BIGINT UNSIGNED;
    DECLARE v_student_user_id BIGINT UNSIGNED;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        SET @allow_submitted_response_change = 0;
        ROLLBACK;
        RESIGNAL;
    END;

    SET v_period_id = p_evaluation_period_id;

    IF v_period_id IS NULL OR v_period_id = 0 THEN
        SELECT evaluation_period_id, term_id
        INTO v_period_id, v_term_id
        FROM evaluation_period
        WHERE period_status IN ('Open','Ongoing')
        ORDER BY evaluation_period_id DESC
        LIMIT 1;
    ELSE
        SELECT term_id
        INTO v_term_id
        FROM evaluation_period
        WHERE evaluation_period_id = v_period_id
        LIMIT 1;
    END IF;

    SELECT user_id
    INTO v_student_user_id
    FROM student
    WHERE student_id = p_student_id
    LIMIT 1;

    START TRANSACTION;

    INSERT INTO evaluation_response_event (
        evaluation_response_id,
        student_evaluation_task_id,
        created_by_user_id,
        event_type,
        event_description
    )
    SELECT
        er.evaluation_response_id,
        setask.student_evaluation_task_id,
        v_student_user_id,
        'Reset Progress',
        COALESCE(p_reset_reason, 'Student reset evaluation progress before logout')
    FROM student_evaluation_task setask
    LEFT JOIN evaluation_response er
        ON er.student_evaluation_task_id = setask.student_evaluation_task_id
       AND er.response_status <> 'Voided'
    WHERE setask.student_id = p_student_id
      AND setask.evaluation_period_id = v_period_id
      AND setask.is_active = 1;

    SET @allow_submitted_response_change = 1;

    UPDATE evaluation_response er
    JOIN student_evaluation_task setask
        ON setask.student_evaluation_task_id = er.student_evaluation_task_id
    SET
        er.response_status = 'Voided',
        er.updated_at = CURRENT_TIMESTAMP
    WHERE setask.student_id = p_student_id
      AND setask.evaluation_period_id = v_period_id
      AND setask.is_active = 1
      AND er.response_status IN ('Draft','Submitted');

    SET @allow_submitted_response_change = 0;

    DELETE era
    FROM evaluation_response_answer era
    JOIN evaluation_response er
        ON er.evaluation_response_id = era.evaluation_response_id
    JOIN student_evaluation_task setask
        ON setask.student_evaluation_task_id = er.student_evaluation_task_id
    WHERE setask.student_id = p_student_id
      AND setask.evaluation_period_id = v_period_id
      AND er.response_status = 'Voided';

    DELETE erc
    FROM evaluation_response_comment erc
    JOIN evaluation_response er
        ON er.evaluation_response_id = erc.evaluation_response_id
    JOIN student_evaluation_task setask
        ON setask.student_evaluation_task_id = er.student_evaluation_task_id
    WHERE setask.student_id = p_student_id
      AND setask.evaluation_period_id = v_period_id
      AND er.response_status = 'Voided';

    UPDATE student_evaluation_task
    SET
        task_status = 'Reset',
        is_active = 0,
        reset_at = CURRENT_TIMESTAMP,
        reset_reason = COALESCE(p_reset_reason, 'Student reset evaluation progress before logout')
    WHERE student_id = p_student_id
      AND evaluation_period_id = v_period_id
      AND is_active = 1;

    INSERT INTO student_evaluation_task (
        student_id,
        teaching_assignment_id,
        evaluation_period_id,
        attempt_no,
        task_status,
        is_active
    )
    SELECT DISTINCT
        p_student_id,
        ta.teaching_assignment_id,
        v_period_id,
        COALESCE((
            SELECT MAX(t2.attempt_no)
            FROM student_evaluation_task t2
            WHERE t2.student_id = p_student_id
              AND t2.teaching_assignment_id = ta.teaching_assignment_id
              AND t2.evaluation_period_id = v_period_id
        ), 0) + 1,
        'Pending',
        1
    FROM student_section_enrollment sse
    JOIN section_subject_offering sso
        ON sso.section_id = sse.section_id
       AND sso.term_id = sse.term_id
       AND sso.offering_status = 'Active'
    JOIN teaching_assignment ta
        ON ta.section_subject_offering_id = sso.section_subject_offering_id
       AND ta.term_id = sso.term_id
       AND ta.assignment_status = 'Active'
    WHERE sse.student_id = p_student_id
      AND sse.term_id = v_term_id
      AND sse.enrollment_status = 'Active'
      AND NOT EXISTS (
          SELECT 1
          FROM student_evaluation_task active_task
          WHERE active_task.student_id = p_student_id
            AND active_task.teaching_assignment_id = ta.teaching_assignment_id
            AND active_task.evaluation_period_id = v_period_id
            AND active_task.is_active = 1
      );

    COMMIT;

    SELECT
        COUNT(*) AS active_tasks_after_reset
    FROM student_evaluation_task
    WHERE student_id = p_student_id
      AND evaluation_period_id = v_period_id
      AND is_active = 1;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_VALUE_ON_ZERO' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `sp_save_evaluation_draft` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_save_evaluation_draft`(IN `p_student_evaluation_task_id` BIGINT UNSIGNED, IN `p_student_id` BIGINT UNSIGNED, IN `p_evaluation_form_id` BIGINT UNSIGNED, IN `p_answers_json` JSON, IN `p_comment_text` TEXT, IN `p_created_by_user_id` BIGINT UNSIGNED)
BEGIN
    DECLARE v_response_id BIGINT UNSIGNED;
    DECLARE v_teaching_assignment_id BIGINT UNSIGNED;
    DECLARE v_evaluation_period_id BIGINT UNSIGNED;
    DECLARE v_existing_status VARCHAR(20);
    DECLARE v_i INT DEFAULT 0;
    DECLARE v_count INT DEFAULT 0;
    DECLARE v_form_item_id BIGINT UNSIGNED;
    DECLARE v_rating_scale_option_id BIGINT UNSIGNED;
    DECLARE v_rating_value TINYINT UNSIGNED;

    SELECT
        teaching_assignment_id,
        evaluation_period_id
    INTO
        v_teaching_assignment_id,
        v_evaluation_period_id
    FROM student_evaluation_task
    WHERE student_evaluation_task_id = p_student_evaluation_task_id
      AND student_id = p_student_id;

    SELECT response_status
    INTO v_existing_status
    FROM evaluation_response
    WHERE student_evaluation_task_id = p_student_evaluation_task_id
    LIMIT 1;

    IF v_existing_status = 'Submitted' THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Submitted evaluation cannot be edited.';
    END IF;

    START TRANSACTION;

    INSERT INTO evaluation_response (
        student_evaluation_task_id,
        student_id,
        teaching_assignment_id,
        evaluation_period_id,
        evaluation_form_id,
        response_status
    )
    VALUES (
        p_student_evaluation_task_id,
        p_student_id,
        v_teaching_assignment_id,
        v_evaluation_period_id,
        p_evaluation_form_id,
        'Draft'
    )
    ON DUPLICATE KEY UPDATE
        evaluation_response_id = LAST_INSERT_ID(evaluation_response_id),
        evaluation_form_id = VALUES(evaluation_form_id),
        response_status = 'Draft',
        updated_at = CURRENT_TIMESTAMP;

    SET v_response_id = LAST_INSERT_ID();

    DELETE FROM evaluation_response_answer
    WHERE evaluation_response_id = v_response_id;

    SET v_count = JSON_LENGTH(p_answers_json);

    WHILE v_i < v_count DO
        SET v_form_item_id = JSON_UNQUOTE(JSON_EXTRACT(p_answers_json, CONCAT('$[', v_i, '].form_item_id')));
        SET v_rating_scale_option_id = JSON_UNQUOTE(JSON_EXTRACT(p_answers_json, CONCAT('$[', v_i, '].rating_scale_option_id')));
        SET v_rating_value = JSON_UNQUOTE(JSON_EXTRACT(p_answers_json, CONCAT('$[', v_i, '].rating_value')));

        INSERT INTO evaluation_response_answer (
            evaluation_response_id,
            evaluation_form_item_id,
            rating_scale_option_id,
            rating_value
        )
        VALUES (
            v_response_id,
            v_form_item_id,
            v_rating_scale_option_id,
            v_rating_value
        );

        SET v_i = v_i + 1;
    END WHILE;

    INSERT INTO evaluation_response_comment (
        evaluation_response_id,
        comment_text,
        is_visible_to_faculty,
        moderation_status
    )
    VALUES (
        v_response_id,
        p_comment_text,
        1,
        'Approved'
    )
    ON DUPLICATE KEY UPDATE
        comment_text = VALUES(comment_text),
        is_visible_to_faculty = 1,
        moderation_status = 'Approved';

    UPDATE student_evaluation_task
    SET
        task_status = 'Draft',
        started_at = IFNULL(started_at, CURRENT_TIMESTAMP),
        last_saved_at = CURRENT_TIMESTAMP
    WHERE student_evaluation_task_id = p_student_evaluation_task_id;

    INSERT INTO evaluation_response_event (
        evaluation_response_id,
        student_evaluation_task_id,
        created_by_user_id,
        event_type,
        event_description
    )
    VALUES (
        v_response_id,
        p_student_evaluation_task_id,
        p_created_by_user_id,
        'Draft Saved',
        'Student saved draft answers.'
    );

    COMMIT;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_VALUE_ON_ZERO' */ ;
