/*!50003 DROP PROCEDURE IF EXISTS `sp_submit_evaluation_response` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_submit_evaluation_response`(IN `p_student_evaluation_task_id` BIGINT UNSIGNED, IN `p_student_id` BIGINT UNSIGNED, IN `p_created_by_user_id` BIGINT UNSIGNED)
BEGIN
    DECLARE v_response_id BIGINT UNSIGNED;
    DECLARE v_period_id BIGINT UNSIGNED;
    DECLARE v_form_id BIGINT UNSIGNED;
    DECLARE v_required_count INT DEFAULT 0;
    DECLARE v_answered_count INT DEFAULT 0;
    DECLARE v_total_score DECIMAL(8,2);
    DECLARE v_average_score DECIMAL(5,2);
    DECLARE v_period_status VARCHAR(20);
    DECLARE v_acceptance_count INT DEFAULT 0;

    SELECT
        er.evaluation_response_id,
        er.evaluation_period_id,
        er.evaluation_form_id
    INTO
        v_response_id,
        v_period_id,
        v_form_id
    FROM evaluation_response er
    WHERE er.student_evaluation_task_id = p_student_evaluation_task_id
      AND er.student_id = p_student_id
      AND er.response_status = 'Draft';

    SELECT period_status
    INTO v_period_status
    FROM evaluation_period
    WHERE evaluation_period_id = v_period_id;

    IF v_period_status NOT IN ('Open','Ongoing') THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Evaluation period is not open.';
    END IF;

    SELECT COUNT(*)
    INTO v_acceptance_count
    FROM guideline_acceptance
    WHERE student_id = p_student_id
      AND evaluation_period_id = v_period_id;

    IF v_acceptance_count = 0 THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Student must accept guidelines before submitting.';
    END IF;

    SELECT COUNT(*)
    INTO v_required_count
    FROM evaluation_form_item efi
    INNER JOIN evaluation_form_category efc
        ON efc.evaluation_form_category_id = efi.evaluation_form_category_id
    WHERE efc.evaluation_form_id = v_form_id
      AND efc.form_category_status = 'Active'
      AND efi.form_item_status = 'Active'
      AND efi.is_required = 1;

    SELECT COUNT(DISTINCT era.evaluation_form_item_id)
    INTO v_answered_count
    FROM evaluation_response_answer era
    INNER JOIN evaluation_form_item efi
        ON efi.evaluation_form_item_id = era.evaluation_form_item_id
    INNER JOIN evaluation_form_category efc
        ON efc.evaluation_form_category_id = efi.evaluation_form_category_id
    WHERE era.evaluation_response_id = v_response_id
      AND efc.evaluation_form_id = v_form_id
      AND efi.is_required = 1;

    IF v_answered_count < v_required_count THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'All required evaluation items must be answered.';
    END IF;

    SELECT
        SUM(rating_value),
        ROUND(AVG(rating_value), 2)
    INTO
        v_total_score,
        v_average_score
    FROM evaluation_response_answer
    WHERE evaluation_response_id = v_response_id;

    START TRANSACTION;

    UPDATE evaluation_response
    SET
        response_status = 'Submitted',
        total_score = v_total_score,
        average_score = v_average_score,
        submitted_at = CURRENT_TIMESTAMP
    WHERE evaluation_response_id = v_response_id;

    UPDATE evaluation_response_comment
    SET submitted_at = CURRENT_TIMESTAMP
    WHERE evaluation_response_id = v_response_id;

    UPDATE student_evaluation_task
    SET
        task_status = 'Submitted',
        submitted_at = CURRENT_TIMESTAMP,
        last_saved_at = CURRENT_TIMESTAMP
    WHERE student_evaluation_task_id = p_student_evaluation_task_id;

    INSERT INTO evaluation_response_event (
        evaluation_response_id,
        student_evaluation_task_id,
        created_by_user_id,
        event_type,
        event_description
    )
    VALUES (
        v_response_id,
        p_student_evaluation_task_id,
        p_created_by_user_id,
        'Submitted',
        'Student confirmed final submission.'
    );

    COMMIT;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_VALUE_ON_ZERO' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `sp_write_audit` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
