DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_write_audit`(IN `p_action_type` VARCHAR(20), IN `p_table_name` VARCHAR(100), IN `p_record_id` BIGINT UNSIGNED, IN `p_old_value_json` JSON, IN `p_new_value_json` JSON)
BEGIN
    INSERT INTO audit_log (
        user_id,
        action_type,
        table_name,
        record_id,
        old_value_json,
        new_value_json,
        ip_address
    )
    VALUES (
        @app_user_id,
        p_action_type,
        p_table_name,
        p_record_id,
        p_old_value_json,
        p_new_value_json,
        @app_ip_address
    );
END ;;
DELIMITER ;
